1	package remote
2	
3	import (
4		"context"
5		"encoding/base64"
6		"fmt"
7		"os"
8		"os/exec"
9		"path/filepath"
10		"strings"
11		"sync"
12	
13		"github.com/entireio/cli/cmd/entire/cli/settings"
14	)
15	
16	// CheckpointTokenEnvVar is the environment variable for providing an access token
17	// used to authenticate git push/fetch operations for checkpoint branches.
18	// The token is injected as an HTTP Basic Authorization header per RFC 7617:
19	// the credentials string "x-access-token:<token>" is base64-encoded and sent as
20	// "Authorization: Basic <base64>". This matches GitHub's token auth for Git HTTPS.
21	// SSH remotes ignore the token (with a warning).
22	const CheckpointTokenEnvVar = "ENTIRE_CHECKPOINT_TOKEN"
23	
24	var sshTokenWarningOnce sync.Once //nolint:gochecknoglobals // intentional per-process gate
25	
26	// FetchOptions configures a git fetch operation.
27	type FetchOptions struct {
28		Remote    string   // remote name or URL (required)
29		RefSpecs  []string // one or more refspecs / object hashes
30		Shallow   bool     // adds --depth=1
31		NoTags    bool     // adds --no-tags
32		NoFilter  bool     // when true, skips --filter=blob:none even if filtered fetches are enabled
33		Dir       string   // working directory (empty = CWD)
34		ExtraArgs []string // additional flags before remote (e.g., "--no-write-fetch-head")
35	}
36	
37	// Fetch runs git fetch with checkpoint token injection and optional
38	// filtered fetches (--filter=blob:none when settings enable it).
39	// GIT_TERMINAL_PROMPT=0 is always set.
40	//
41	// Callers that pass a remote name (e.g., "origin") and want filtered fetches to
42	// resolve the name to a URL (to avoid persisting promisor settings) should call
43	// ResolveFetchTarget first and pass the resolved target as opts.Remote.
44	func Fetch(ctx context.Context, opts FetchOptions) ([]byte, error) {
45		args := []string{"fetch"}
46		if opts.NoTags {
47			args = append(args, "--no-tags")
48		}
49		if opts.Shallow {
50			args = append(args, "--depth=1")
51		}
52		args = append(args, opts.ExtraArgs...)
53		if !opts.NoFilter && settings.IsFilteredFetchesEnabled(ctx) {
54			args = append(args, "--filter=blob:none")
55		}
56		args = append(args, opts.Remote)
57		args = append(args, opts.RefSpecs...)
58	
59		cmd := newCommand(ctx, args...)
60		if opts.Dir != "" {
61			cmd.Dir = opts.Dir
62		}
63		disableTerminalPrompt(cmd)
64		out, err := cmd.CombinedOutput()
65		if err != nil {
66			return out, fmt.Errorf("git fetch: %w", err)
67		}
68		return out, nil
69	}
70	
71	// FetchBlobs fetches specific objects (typically blobs) by hash from a remote.
72	// Unlike Fetch, this never applies --filter=blob:none (which would be
73	// contradictory — the point is to download specific blobs) and always uses
74	// --no-write-fetch-head to avoid polluting FETCH_HEAD.
75	//
76	// The remote should be a URL (not a remote name) to avoid persisting promisor
77	// settings onto the named remote. Use resolveCheckpointFetchTarget or
78	// FetchURL to obtain the URL.
79	func FetchBlobs(ctx context.Context, remote string, hashes []string) error {
80		args := []string{"fetch", "--no-tags", "--no-write-fetch-head", remote}
81		args = append(args, hashes...)
82	
83		cmd := newCommand(ctx, args...)
84		disableTerminalPrompt(cmd)
85		_, err := cmd.CombinedOutput()
86		if err != nil {
87			return fmt.Errorf("git fetch blobs: %w", err)
88		}
89		return nil
90	}
91	
92	// PushResult holds raw porcelain output from git push.
93	type PushResult struct {
94		Output string
95	}
96	
97	// Push runs git push --no-verify --porcelain with token injection.
98	// GIT_TERMINAL_PROMPT=0 is always set.
99	func Push(ctx context.Context, remote, refSpec string) (PushResult, error) {
100		pushTarget, err := resolvePushCommandTarget(ctx, remote)
101		if err != nil {
102			return PushResult{}, fmt.Errorf("resolve push target: %w", err)
103		}
104	
105		cmd := newCommand(ctx, "push", "--no-verify", "--porcelain", pushTarget, refSpec)
106		disableTerminalPrompt(cmd)
107		output, err := cmd.CombinedOutput()
108		if err != nil {
109			return PushResult{Output: string(output)}, fmt.Errorf("git push: %w", err)
110		}
111		return PushResult{Output: string(output)}, nil
112	}
113	
114	// LsRemote runs git ls-remote with token injection.
115	// GIT_TERMINAL_PROMPT=0 is always set. Returns stdout only.
116	func LsRemote(ctx context.Context, remote string, patterns ...string) ([]byte, error) {
117		return lsRemote(ctx, "", remote, patterns...)
118	}
119	
120	// LsRemoteInDir is like LsRemote but runs in a specific directory.
121	func LsRemoteInDir(ctx context.Context, dir, remote string, patterns ...string) ([]byte, error) {
122		return lsRemote(ctx, dir, remote, patterns...)
123	}
124	
125	func lsRemote(ctx context.Context, dir, remote string, patterns ...string) ([]byte, error) {
126		args := append([]string{"ls-remote", remote}, patterns...)
127		cmd := newCommand(ctx, args...)
128		if dir != "" {
129			cmd.Dir = dir
130		}
131		disableTerminalPrompt(cmd)
132		out, err := cmd.Output()
133		if err != nil {
134			return out, fmt.Errorf("git ls-remote: %w", err)
135		}
136		return out, nil
137	}
138	
139	// IsURL returns true if the target looks like a URL rather than a git remote name.
140	func IsURL(target string) bool {
141		return strings.Contains(target, "://") || strings.Contains(target, "@")
142	}
143	
144	// ResolveFetchTarget returns the git fetch target to use. When filtered
145	// fetches are enabled, configured remotes are resolved to their URL so git does
146	// not persist promisor settings onto the remote name.
147	func ResolveFetchTarget(ctx context.Context, target string) (string, error) {
148		if IsURL(target) || !settings.IsFilteredFetchesEnabled(ctx) {
149			return target, nil
150		}
151		url, err := GetRemoteURL(ctx, target)
152		if err != nil {
153			return "", fmt.Errorf("get remote URL: %w", err)
154		}
155		return url, nil
156	}
157	
158	// newCommand creates an exec.Cmd for a git operation that may need
159	// checkpoint token authentication. If ENTIRE_CHECKPOINT_TOKEN is set and the
160	// remote in args resolves to an HTTPS URL, a Basic auth token is injected via
161	// GIT_CONFIG_COUNT/GIT_CONFIG_KEY_*/GIT_CONFIG_VALUE_* environment variables.
162	//
163	// For SSH remotes, a warning is printed once to stderr and the token is not injected.
164	// For empty/unset tokens, the command is returned unmodified.
165	//
166	// The remote is extracted from args by skipping the git subcommand and any flags
167	// (arguments starting with "-"). For example, in
168	// ["push", "--no-verify", "origin", "main"], the remote is "origin".
169	func newCommand(ctx context.Context, args ...string) *exec.Cmd {
170		cmd := exec.CommandContext(ctx, "git", args...)
171		cmd.Stdin = nil // Disconnect stdin to prevent hanging in hook context
172	
173		token := strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar))
174		if token == "" {
175			return cmd
176		}
177	
178		if !isValidToken(token) {
179			fmt.Fprintf(os.Stderr, "[entire] Warning: %s contains invalid characters (CR, LF, or other control chars) — token ignored\n", CheckpointTokenEnvVar)
180			return cmd
181		}
182	
183		target := extractRemoteFromArgs(args)
184		if target == "" {
185			return cmd
186		}
187	
188		protocol := resolveTargetProtocol(ctx, target)
189	
190		switch protocol {
191		case ProtocolSSH:
192			sshTokenWarningOnce.Do(func() {
193				fmt.Fprintf(os.Stderr, "[entire] Warning: %s is set but remote uses SSH — token ignored for SSH remotes\n", CheckpointTokenEnvVar)
194			})
195			return cmd
196		case ProtocolHTTPS:
197			cmd.Env = appendCheckpointTokenEnv(os.Environ(), token)
198			return cmd
199		default:
200			// Unknown protocol (e.g., local path, or resolution failed) — don't inject
201			return cmd
202		}
203	}
204	
205	// extractRemoteFromArgs finds the remote URL or name from git command args.
206	// It skips the subcommand (first arg) and any flags (args starting with "-"),
207	// returning the first positional argument, which is the remote for push/fetch/ls-remote.
208	func extractRemoteFromArgs(args []string) string {
209		if len(args) < 2 {
210			return ""
211		}
212		// Skip subcommand (e.g., "push", "fetch", "ls-remote").
213		for _, arg := range args[1:] {
214			if !strings.HasPrefix(arg, "-") {
215				return arg
216			}
217		}
218		return ""
219	}
220	
221	// appendCheckpointTokenEnv appends GIT_CONFIG_COUNT-based env vars to inject
222	// an Authorization header into git HTTP requests. The token is sent as a Basic
223	// credential with the format "x-access-token:<token>" (base64-encoded), which
224	// is compatible with GitHub's token authentication.
225	// It filters out any pre-existing GIT_CONFIG_COUNT/KEY/VALUE entries to avoid
226	// conflicts, then appends the new ones.
227	//
228	// NOTE: This drops ALL existing GIT_CONFIG_* entries from the environment.
229	// If a parent process (e.g., CI) injects its own GIT_CONFIG_* vars, they will
230	// be lost. If that becomes an issue, read the existing count and append at the
231	// next index instead of replacing.
232	func appendCheckpointTokenEnv(baseEnv []string, token string) []string {
233		filtered := make([]string, 0, len(baseEnv)+3)
234		for _, e := range baseEnv {
235			if strings.HasPrefix(e, "GIT_CONFIG_COUNT=") ||
236				strings.HasPrefix(e, "GIT_CONFIG_KEY_") ||
237				strings.HasPrefix(e, "GIT_CONFIG_VALUE_") {
238				continue
239			}
240			filtered = append(filtered, e)
241		}
242		encoded := base64.StdEncoding.EncodeToString([]byte("x-access-token:" + token))
243		return append(filtered,
244			"GIT_CONFIG_COUNT=1",
245			"GIT_CONFIG_KEY_0=http.extraHeader",
246			"GIT_CONFIG_VALUE_0=Authorization: Basic "+encoded,
247		)
248	}
249	
250	// isValidToken returns false if the token contains control characters (bytes < 0x20
251	// or 0x7F). This prevents HTTP header injection via CR/LF or other control chars
252	// embedded in the token value.
253	func isValidToken(token string) bool {
254		for _, b := range []byte(token) {
255			if b < 0x20 || b == 0x7F {
256				return false
257			}
258		}
259		return true
260	}
261	
262	// resolveTargetProtocol determines whether a push/fetch target uses SSH or HTTPS.
263	// Returns ProtocolSSH, ProtocolHTTPS, or "" if unknown.
264	func resolveTargetProtocol(ctx context.Context, target string) string {
265		var rawURL string
266		if IsURL(target) {
267			rawURL = target
268		} else {
269			// Remote name — resolve to URL
270			var err error
271			rawURL, err = GetRemoteURL(ctx, target)
272			if err != nil {
273				return ""
274			}
275		}
276	
277		info, err := ParseURL(rawURL)
278		if err != nil {
279			return ""
280		}
281		return info.Protocol
282	}
283	
284	func resolvePushCommandTarget(ctx context.Context, target string) (string, error) {
285		if target == "" || IsURL(target) || isLocalPath(target) {
286			return target, nil
287		}
288	
289		pushTarget, _, err := PushURL(ctx, target)
290		if err != nil {
291			return "", err
292		}
293		if pushTarget == "" {
294			return target, nil
295		}
296		return pushTarget, nil
297	}
298	
299	func isLocalPath(target string) bool {
300		return filepath.IsAbs(target) || strings.HasPrefix(target, "./") || strings.HasPrefix(target, "../")
301	}
302	
303	// disableTerminalPrompt sets GIT_TERMINAL_PROMPT=0 on the command,
304	// initializing cmd.Env from os.Environ() if nil.
305	func disableTerminalPrompt(cmd *exec.Cmd) {
306		if cmd.Env == nil {
307			cmd.Env = os.Environ()
308		}
309		cmd.Env = append(cmd.Env, "GIT_TERMINAL_PROMPT=0")
310	}
