1	package remote
2	
3	import (
4		"context"
5		"fmt"
6		"log/slog"
7		"os"
8		"strings"
9	
10		"github.com/entireio/cli/cmd/entire/cli/gitremote"
11		"github.com/entireio/cli/cmd/entire/cli/logging"
12		"github.com/entireio/cli/cmd/entire/cli/settings"
13	)
14	
15	const (
16		originRemote          = "origin"
17		checkpointTokenEnvVar = "ENTIRE_CHECKPOINT_TOKEN"
18	)
19	
20	const (
21		ProtocolSSH   = gitremote.ProtocolSSH
22		ProtocolHTTPS = gitremote.ProtocolHTTPS
23	)
24	
25	// Info is an alias for gitremote.Info.
26	type Info = gitremote.Info
27	
28	// FetchURL returns the effective checkpoint fetch URL for the current repository.
29	// If strategy_options.checkpoint_remote is configured, the returned URL is derived
30	// from the origin remote's protocol/host and the configured checkpoint repo.
31	// Otherwise, the origin remote URL is returned directly.
32	//
33	// If ENTIRE_CHECKPOINT_TOKEN is set and a checkpoint remote is configured, HTTPS is
34	// forced so the token can be used even when origin is configured via SSH.
35	func FetchURL(ctx context.Context) (string, error) {
36		withToken := strings.TrimSpace(os.Getenv(checkpointTokenEnvVar)) != ""
37	
38		originURL, originErr := GetRemoteURL(ctx, originRemote)
39		if originErr != nil {
40			originURL = ""
41		}
42	
43		if originURL != "" && withToken {
44			if tokenURL, ok := deriveTokenOriginURL(originURL); ok {
45				originURL = tokenURL
46			}
47		}
48	
49		s, err := settings.Load(ctx)
50		if err != nil {
51			if originURL != "" {
52				logFallback(ctx, "fetch", originURL, "load settings", err)
53				return originURL, nil
54			}
55			return "", fmt.Errorf("load settings: %w", err)
56		}
57	
58		config := s.GetCheckpointRemote()
59		if config == nil {
60			if originURL == "" {
61				return "", fmt.Errorf("no fetch URL found: %w", originErr)
62			}
63			return originURL, nil
64		}
65	
66		if withToken {
67			host, ok := providerHost(config.Provider)
68			if ok {
69				checkpointURL, err := deriveCheckpointURLFromInfo(&Info{
70					Protocol: ProtocolHTTPS,
71					Host:     host,
72				}, config)
73				if err == nil {
74					return checkpointURL, nil
75				}
76			}
77	
78			// In token-based execution path, short-circuit to avoid additional
79			// change in protocol.
80			if originURL != "" {
81				return originURL, nil
82			}
83		}
84	
85		if originURL == "" {
86			return "", fmt.Errorf("no fetch URL found: %w", originErr)
87		}
88	
89		info, err := ParseURL(originURL)
90		if err != nil {
91			logFallback(ctx, "fetch", originURL, "parse origin remote URL", err)
92			return originURL, nil
93		}
94	
95		checkpointURL, err := deriveCheckpointURLFromInfo(info, config)
96		if err != nil {
97			logFallback(ctx, "fetch", originURL, "derive checkpoint remote URL", err)
98			return originURL, nil
99		}
100	
101		return checkpointURL, nil
102	}
103	
104	// PushURL returns the effective checkpoint push URL for the current repository.
105	// Unlike FetchURL:
106	//   - it derives protocol from the requested push remote, not always origin
107	//   - it skips checkpoint remote use when the push remote owner differs
108	//     from the configured checkpoint remote owner
109	//
110	// If ENTIRE_CHECKPOINT_TOKEN is set, HTTPS is forced so the token can be used
111	// even when the push remote is configured via SSH.
112	//
113	// The boolean return value reports whether a dedicated checkpoint_remote is
114	// configured and should be used for push. When false, the returned URL is the
115	// repository's origin URL as a fallback.
116	func PushURL(ctx context.Context, pushRemoteName string) (string, bool, error) {
117		originURL := ""
118		if resolvedOriginURL, err := GetRemoteURL(ctx, originRemote); err == nil {
119			originURL = resolvedOriginURL
120		}
121	
122		s, err := settings.Load(ctx)
123		if err != nil {
124			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
125			if fallbackErr == nil {
126				logFallback(ctx, "push", fallbackURL, "load settings", err,
127					slog.String("push_remote", pushRemoteName),
128				)
129				return fallbackURL, false, nil
130			}
131			return "", false, fmt.Errorf("load settings: %w", err)
132		}
133	
134		config := s.GetCheckpointRemote()
135		if config == nil {
136			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
137			if fallbackErr != nil {
138				return "", false, fmt.Errorf("no push URL found: %w", fallbackErr)
139			}
140			return fallbackURL, false, nil
141		}
142	
143		pushRemoteURL, err := GetRemoteURL(ctx, pushRemoteName)
144		if err != nil {
145			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
146			if fallbackErr == nil {
147				logFallback(ctx, "push", fallbackURL, "get push remote URL", err,
148					slog.String("push_remote", pushRemoteName),
149				)
150				return fallbackURL, false, nil
151			}
152			return "", true, fmt.Errorf("no push URL found: %w", err)
153		}
154	
155		pushInfo, err := ParseURL(pushRemoteURL)
156		if err != nil {
157			if originURL != "" {
158				logFallback(ctx, "push", originURL, "parse push remote URL", err,
159					slog.String("push_remote", pushRemoteName),
160				)
161				return originURL, false, nil
162			}
163			return "", true, fmt.Errorf("no push URL found: %w", err)
164		}
165		if strings.TrimSpace(os.Getenv(checkpointTokenEnvVar)) != "" {
166			pushInfo = &Info{
167				Protocol: ProtocolHTTPS,
168				Host:     pushInfo.Host,
169				Owner:    pushInfo.Owner,
170				Repo:     pushInfo.Repo,
171			}
172		}
173	
174		checkpointOwner := config.Owner()
175		if pushInfo.Owner != "" && checkpointOwner != "" && !strings.EqualFold(pushInfo.Owner, checkpointOwner) {
176			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
177			if fallbackErr != nil {
178				return "", false, fmt.Errorf("no push URL found: %w", fallbackErr)
179			}
180			return fallbackURL, false, nil
181		}
182	
183		pushURL, err := deriveCheckpointURLFromInfo(pushInfo, config)
184		if err != nil {
185			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
186			if fallbackErr == nil {
187				logFallback(ctx, "push", fallbackURL, "derive push checkpoint URL", err,
188					slog.String("push_remote", pushRemoteName),
189				)
190				return fallbackURL, false, nil
191			}
192			return "", true, fmt.Errorf("no push URL found: %w", err)
193		}
194	
195		return pushURL, true, nil
196	}
197	
198	// Configured reports whether a structured checkpoint_remote is configured.
199	func Configured(ctx context.Context) bool {
200		s, err := settings.Load(ctx)
201		if err != nil {
202			logging.Warn(ctx, "checkpoint remote configuration unavailable; treating as not configured",
203				slog.String("error", err.Error()),
204			)
205			return false
206		}
207		return s.GetCheckpointRemote() != nil
208	}
209	
210	// GetRemoteURL returns the URL configured for the named git remote.
211	func GetRemoteURL(ctx context.Context, remoteName string) (string, error) {
212		url, err := gitremote.GetRemoteURL(ctx, remoteName)
213		if err != nil {
214			return "", fmt.Errorf("get remote URL: %w", err)
215		}
216		return url, nil
217	}
218	
219	// ParseURL parses a git remote URL (SSH SCP-style or HTTPS) into its components.
220	func ParseURL(rawURL string) (*Info, error) {
221		info, err := gitremote.ParseURL(rawURL)
222		if err != nil {
223			return nil, fmt.Errorf("parse URL: %w", err)
224		}
225		return info, nil
226	}
227	
228	func DeriveCheckpointURL(pushRemoteURL string, config *settings.CheckpointRemoteConfig) (string, error) {
229		info, err := gitremote.ParseURL(pushRemoteURL)
230		if err != nil {
231			return "", fmt.Errorf("cannot parse push remote URL: %w", err)
232		}
233		return deriveCheckpointURLFromInfo(info, config)
234	}
235	
236	// ExtractOwnerFromRemoteURL extracts the owner component from a git remote URL.
237	func ExtractOwnerFromRemoteURL(rawURL string) string {
238		return gitremote.ExtractOwnerFromRemoteURL(rawURL)
239	}
240	
241	func deriveCheckpointURLFromInfo(info *Info, config *settings.CheckpointRemoteConfig) (string, error) {
242		switch info.Protocol {
243		case ProtocolSSH:
244			// SCP-style (git@host:repo) doesn't support ports. When Host includes
245			// a port (e.g., from ssh://git@host:2222/...), use the ssh:// URL form.
246			if strings.Contains(info.Host, ":") {
247				return fmt.Sprintf("ssh://git@%s/%s.git", info.Host, config.Repo), nil
248			}
249			return fmt.Sprintf("git@%s:%s.git", info.Host, config.Repo), nil
250		case ProtocolHTTPS:
251			return fmt.Sprintf("https://%s/%s.git", info.Host, config.Repo), nil
252		default:
253			return "", fmt.Errorf("unsupported protocol %q in origin remote", info.Protocol)
254		}
255	}
256	
257	func deriveTokenOriginURL(originURL string) (string, bool) {
258		info, err := gitremote.ParseURL(originURL)
259		if err != nil {
260			return "", false
261		}
262		if info.Host == "" || info.Owner == "" || info.Repo == "" {
263			return "", false
264		}
265		return fmt.Sprintf("https://%s/%s/%s.git", info.Host, info.Owner, info.Repo), true
266	}
267	
268	func providerHost(provider string) (string, bool) {
269		switch strings.ToLower(strings.TrimSpace(provider)) {
270		case "github":
271			return "github.com", true
272		case "gitlab":
273			return "gitlab.com", true
274		default:
275			return "", false
276		}
277	}
278	
279	// RedactURL removes credentials and query parameters from a URL for safe logging.
280	func RedactURL(rawURL string) string {
281		return gitremote.RedactURL(rawURL)
282	}
283	
284	func logFallback(ctx context.Context, operation, fallbackURL, reason string, err error, attrs ...any) {
285		logAttrs := []any{
286			slog.String("operation", operation),
287			slog.String("fallback_url", RedactURL(fallbackURL)),
288			slog.String("reason", reason),
289			slog.String("error", err.Error()),
290		}
291		logAttrs = append(logAttrs, attrs...)
292		logging.Warn(ctx, "checkpoint remote URL resolution fell back to alternate remote URL", logAttrs...)
293	}
294	
295	func resolvePushFallbackURL(ctx context.Context, pushRemoteName, originURL string) (string, error) {
296		if originURL != "" {
297			if strings.TrimSpace(os.Getenv(checkpointTokenEnvVar)) != "" {
298				if tokenURL, ok := deriveTokenOriginURL(originURL); ok {
299					return tokenURL, nil
300				}
301			}
302			return originURL, nil
303		}
304		if pushRemoteName == "" || pushRemoteName == originRemote {
305			return "", fmt.Errorf("remote %q not found", originRemote)
306		}
307		pushURL, err := GetRemoteURL(ctx, pushRemoteName)
308		if err != nil {
309			return "", err
